  }), mdx("p", null, "\uC2A4\uBB34\uC0B4 \uCD08\uBC18\uC5D0 \uD559\uC0DD \uC0AC\uD68C \uCC38\uC5EC\uD558\uACE0 \uC18C\uC218\uC790 \uC639\uD638\uD558\uACE0 \uC6B4\uB3D9\uAD8C \uCC0C\uB77C\uC2DC\uB77C\uACE0 \uC0AC\uB78C\uB4E4\uC774 \uB5A0\uB4E4\uB358 \uAC83 \uB9CC\uB4E4\uC5C8\uB2E4. \uC778\uC0DD\uC5D0\uC11C \uAC00\uC7A5 \uBD88\uD589\uD55C \uB54C\uB77C\uACE0 \uD655\uC2E0\uD55C\uB2E4. \uBCF4\uB78C \uB530\uC704\uAC00 \uC804\uBB34\uD558\uACE0 \uAC1C\uC778\uC801\uC778 \uBD88\uC774\uC775\uB9CC \uB9CE\uC544\uC11C \uBAB9\uC2DC \uC790\uC870\uD588\uB2E4. \uB098\uB97C \uB458\uB7EC\uC2FC \uC138\uC0C1\uC740 \uC870\uAE08\uB3C4 \uB098\uC544\uC9C0\uC9C0\uAC00 \uC54A\uACE0 \uBC30\uC54C\uB9CC \uAF34\uB838\uB2E4."), mdx("p", null, "\uCDE8\uC5C5 \uAC19\uC740 \uAC83 \uC0DD\uAC01 \uC548\uD558\uACE0 \uC774\uB807\uAC8C \uC778\uC0DD\uC744 \uAF2C\uACE0 \uC788\uB294\uAC8C \uCC38 \uD55C\uC2EC\uD574 \uBCF4\uC600\uB2E4. \uD559\uC0DD\uCC98\uC7A5\uC774 \uB610\uB294 \uB204\uAD6C \uAD50\uC218\uAC00 \uB0A0 \uC54C\uACE0 \uBABB \uC0B4\uAC8C \uAD6C\uB294\uB370 \uD559\uAD50 \uBB34\uC0AC\uD788 \uB2E4\uB2C8\uB294 \uAC8C \uAC00\uB2A5\uC740 \uD55C\uC9C0 \uC758\uBB38\uC774\uC5C8\uB2E4. \uD398\uC774\uC2A4\uBD81\uC5D0\uC11C \uC0AC\uB78C\uB4E4\uACFC \uD0A4\uBCF4\uB4DC \uBC30\uD2C0\uC744 \uB108\uBB34 \uB9CE\uC774 \uD574\uB300\uB294 \uD1B5\uC5D0 \uC0C1\uCC98\uB97C \uB108\uBB34 \uB9CE\uC774 \uBC1B\uC558\uB2E4. \uAE30\uC790\uB85C \uC788\uC5C8\uB358 \uB3C5\uB9BD\uC5B8\uB860 \uC2E0\uC785\uAE30\uC790 \uBAA8\uC9D1 \uD3EC\uC2A4\uD130\uC5D0 \"\uC778\uC0DD\uC758 \uAD74\uACE1 \uBAA8\uC790\uB77C\uC2E0 \uBD84 \uBAA8\uC2ED\uB2C8\uB2E4.\"\uB77C\uACE0 \uAD81\uC11C\uCCB4\uB85C \uC368\uB193\uACE0 \uD300\uC6D0\uB4E4\uACFC \uB084\uB084\uB314\uB2E4."), mdx("p", null, "\uC65C \uADF8\uB807\uAC8C \uC0B4\uC558\uB294\uC9C0 \uB3CC\uC544\uBCF4\uBA74, \uC815\uB9D0 \uD559\uAD50\uB098 \uC0AC\uD68C\uB97C \uBC14\uAFC0 \uC218 \uC788\uB2E4\uB294 \uD655\uC2E0\uC5D0 \uCC28\uC11C \uADF8\uB7F0 \uD65C\uB3D9\uC744 \uD588\uB358 \uAC74 \uC544\uB2C8\uC5C8\uB2E4. \uADF8\uB0E5 \uC774\uB807\uAC8C \uC548\uD558\uBA74 \uB0B4\uAC00 \uC886\uB420 \uAC83 \uAC19\uC544\uC11C \uD588\uB2E4."), mdx("p", null, "\uB098\uB97C \uB458\uB7EC\uC2FC \uACF5\uB3D9\uCCB4\uC640 \uC138\uC0C1\uC774 \uC774 \uC815\uB3C4\uBC16\uC5D0 \uC548\uB418\uB098? \uB0B4\uAC00 \uD560 \uC218 \uC788\uB294\uAC8C \uC815\uB9D0 \uD558\uB098\uB3C4 \uC5C6\uC744\uAE4C? \uB098\uB77C\uB3C4 \uBB50\uB77C\uB3C4 \uD558\uC9C0 \uC54A\uC73C\uBA74 \uC9C4\uC9DC \uB0B4\uAC00 \uC0AC\uB294 \uC138\uC0C1\uC5D0\uC11C \uC88B\uC740 \uAD6C\uC11D\uC774\uB780 \uC544\uBB34\uAC83\uB3C4 \uB0A8\uC544\uC788\uC9C0 \uC54A\uC744 \uAC83 \uAC19\uC558\uB2E4. \uADF8 \uC18D\uC5D0 \uC0B4\uC544\uAC00\uB294 \uB098\uB3C4 \uC2A4\uB7EC\uC9C8 \uAC83 \uAC19\uC558\uB2E4. \uC774\uB7F0 \uC0DD\uAC01\uB4E4\uC5D0\uC11C \uC870\uAE08\uC774\uB77C\uB3C4 \uC790\uC720\uB85C\uC6CC\uC9C0\uB824\uBA74 \uC6B0\uC6B8\uACFC \uBD88\uD3B8 \uC18D\uC5D0\uC11C\uB3C4 \uADF8 \uD2C8\uBC14\uAD6C\uB2C8\uC5D0 \uAE30\uAEBC\uC774 \uC788\uC5B4\uC57C\uB9CC \uD588\uB358 \uAC83 \uAC19\uB2E4. \uBB34\uC5B8\uAC00\uB97C \uD558\uAE30\uB294 \uD574\uC57C \uD588\uB2E4."), mdx("p", null, "\uC720\uD29C\uBE0C\uB97C \uB4A4\uC801\uC774\uB2E4 \uACFC\uAC70 \uBC29\uC1A1 \uD074\uB9BD\uC5D0\uC11C, ", mdx("a", {
