    "href": "https://youtu.be/dztNg4fJtS0?t=1402"
  }, "\uC720\uC2DC\uBBFC \uC791\uAC00\uAC00 \uC65C \uC790\uC2E0\uC774 \uD559\uC0DD\uC6B4\uB3D9\uC5D0 \uCC38\uC5EC\uD588\uB294\uC9C0\uB97C"), " \uB9D0\uD558\uB294 \uC7A5\uBA74\uC744 \uBD24\uB2E4. \uC778\uC6A9\uD558\uBA74 \"\uB0B4 \uC0B6\uC758 \uBC29\uC2DD\uC5D0 \uBE44\uCC38\uD568\uACFC \uBE44\uAC81\uD568\uC744 \uB290\uB07C\uACE0 \uC2F6\uC9C0 \uC54A\uC544\uC11C\". \"\uBABB \uC774\uAE38 \uAC83 \uAC19\uC740\uB370 \uADF8\uB300\uB85C \uADF8\uB0E5 \uAC00\uBA74 \uB108\uBB34 \uBE44\uCC38\uD55C\uAC70\uC57C\", \"\uB54C\uB85C \uC0AC\uB78C\uC740 \uC790\uAE30\uB97C \uC9C0\uD0A4\uAE30 \uC704\uD574 \uADF8\uB7F0 \uC77C\uC744 \uD574\uC694.\", \"\uB0B4\uAC00 \uC548 \uD55C\uB2E4\uACE0 \uD574\uC11C \uB204\uAC00 \uB098\uBCF4\uACE0 \uC695\uD558\uC9C0 \uC54A\uC544\uC694.\", \"\uACE0\uC0DD\uC740 \uC880 \uD558\uAE30\uB294 \uD588\uB294\uB370, \uB0B4 \uC790\uC2E0\uC758 \uC0B6\uC5D0 \uB300\uD574\uC11C \uBE44\uCC38\uD558\uB2E4\uACE0 \uC0DD\uAC01\uD558\uC9C0\uB294 \uC54A\uACE0 \uC0B4\uC558\uC5B4\uC694.\""), mdx("p", null, "\uB0B4 \uC2F8\uC6C0\uC740 \uAD70\uC0AC\uC815\uAD8C \uD56D\uAC70\uBCF4\uB2E4 \uC791\uC558\uB2E4. \uD6D7\uB0A0 \uB0B4 \uC778\uC0DD\uC5D0 \uB300\uD574 \uC5B4\uB5BB\uAC8C \uB290\uB084\uC9C0 \uC0DD\uAC01\uD558\uBA70 \uD589\uD558\uC9C0\uB3C4 \uC54A\uC558\uB2E4. \uAC83\uBCF4\uB2E8 \uD6E8\uC52C \uADFC\uC2DC\uC548\uC801\uC774\uACE0 \uC0DD\uAC01 \uC5C6\uC5C8\uB2E4. \uADF8\uB807\uC9C0\uB9CC \uB098\uB3C4 \uB098\uB97C \uC9C0\uD0A4\uAE30 \uC704\uD574 \uADF8\uB7F0 \uC77C\uC744 \uD558\uAC8C \uB418\uC5C8\uB2E4. \uC9C0\uAE08 \uC774\uB807\uAC8C \uC0B4\uC544\uAC08 \uC218 \uC788\uB294\uAC00? \uC544\uB2C8\uB2E4. \uC544\uB2C8\uB77C\uACE0."), mdx("p", null, "--"), mdx("p", null, "\uAC1C\uBC1C\uC790\uB85C \uC77C\uD558\uB294 \uD68C\uC0AC\uC5D0\uC11C 1\uB144\uC9F8 \uD558\uB098\uC758 \uD504\uB85C\uC81D\uD2B8\uB97C \uACC4\uC18D \uC9C4\uD589\uD558\uACE0 \uC788\uB2E4. \uB0B4\uAC00 \uD574 \uBCF8 \uBAA8\uB4E0 \uC885\uB958\uC758 \uC77C \uC911\uC5D0 \uC5B4\uB835\uACE0 \uC624\uB798 \uAC78\uB9AC\uAE30\uB85C \uC190\uC5D0 \uAF3D\uB294\uB2E4."), mdx("p", null, "\uB300\uCDA9 \uC124\uBA85\uD558\uC790\uBA74 \uD3ED\uD0C4 \uD574\uCCB4\uAC19\uC740 \uC77C\uC774\uB2E4. \uAE30\uACC4\uB97C \uC774\uB8E8\uB294 \uBD80\uD488\uACFC \uC804\uC120\uB4E4\uC774 \uADDC\uCE59\uC5C6\uC774 \uC5BD\uD600\uC788\uB294 \uC0C1\uD669\uC5D0\uC11C \uD2B9\uC815 \uBD80\uBD84\uB4E4\uC744 \uC548\uC804\uD558\uAC8C \uC81C\uAC70\uD558\uACE0 \uC815\uB9AC\uD574\uC11C \uB354 \uB098\uC740 \uC124\uACC4\uB85C \uB3D9\uC791\uD558\uAC8C \uB9CC\uB4E4\uC5B4\uC57C \uD55C\uB2E4. \uCD5C\uADFC\uC5D0 \uAF64\uB098 \uBCBD\uC5D0 \uBD80\uB52A\uD614\uB2E4. \uB108\uBB34 \uBCF5\uC7A1\uD574\uC11C \uBAA8\uB4E0 \uBCC0\uC218\uC640 \uBB38\uC81C\uB97C \uD1B5\uC81C\uD560 \uC218 \uC5C6\uC744 \uAC83 \uAC19\uB2E4\uB294 \uC0DD\uAC01\uC774 \uB9CE\uC774 \uB4E4\uC5C8\uB2E4. \uBB38\uC81C\uC5D0 \uC555\uB3C4\uB2F9\uD588\uB2E4. \uC544\uCE68\uC5D0 \uCD9C\uADFC\uD574 \uC549\uC73C\uBA74 \uC885\uC885 \uBA85\uCE58 \uB05D\uC774 \uB728\uAC70\uC6CC\uC84C\uB2E4."), mdx("p", null, "\uC774\uC9C1\uD55C \uCE5C\uAD6C\uAC00 \"\uC774\uC9C1\uD558\uACE0 \uAC00\uC7A5 \uC88B\uC740 \uC810\uC740 \uC5EC\uAE30\uC5D4 \uB0B4\uAC00 \uB9CC\uB4E4\uC5B4\uB0B8 \uCF54\uB4DC\uAC00 \uC5C6\uB2E4\uB294 \uAC70\uC57C\" \uB77C\uB294 \uB9D0\uC744 \uD55C \uC801\uC774 \uC788\uC5C8\uB294\uB370 \uC9C4\uC9DC \uC5C4\uCCAD, \uC5C4\uCCAD \uBD80\uB7EC\uC6E0\uB2E4. \uB0B4\uAC00 \uD480\uACE0 \uC788\uB294 \uBB38\uC81C\uB098 \uACFC\uAC70\uC758 \uC2E4\uC218\uAC00 \uBAA8\uB450 \uC5C6\uC5B4\uC9C0\uACE0, \uAE68\uB057\uD55C \uC0C1\uD0DC\uC5D0\uC11C \uB2E4\uC2DC \uBB54\uAC00 \uC2DC\uC791\uD558\uB294 \uAC10\uAC01\uC774 \uC815\uB9D0 \uC88B\uC744 \uAC83 \uAC19\uB2E4. \uB35C \uACE0\uD1B5\uC2A4\uB7EC\uC6B8 \uAC83 \uAC19\uB2E4."), mdx("p", null, "\uD558\uC9C0\uB9CC \uAC70\uAE30\uC11C, \uB098\uB294 \uADF8\uB807\uAC8C\uB294 \uD560 \uC218 \uC5C6\uB2E4\uACE0 \uB098\uC5D0\uAC8C \uAC15\uD558\uAC8C \uC8FC\uC7A5\uD588\uB2E4. \uB0B4\uAC00 \uBB38\uC81C\uB97C \uD574\uACB0\uD558\uC9C0 \uBABB\uD558\uB294 \uC0C1\uD669\uC774 \uB0A8\uC544\uC788\uAC8C \uD558\uACE0 \uC2F6\uC9C0 \uC54A\uB2E4. \uC5EC\uAE30\uC11C \uADF8\uB9CC\uB454\uB2E4\uBA74? \uB098\uB294 \uADF8\uB807\uAC8C \uC0B4\uC544\uAC08 \uC218\uB294 \uC5C6\uB2E4. \uB0B4\uAC00 \uD478\uB294 \uBB38\uC81C \uACB0\uAD6D \uB0B4\uAC00 \uD574\uACB0\uD560 \uC218 \uC5C6\uB294 \uAC83\uC778\uAC00? \uD558\uBA74 \uCD5C\uC120\uC744 \uB2E4\uD574 \uBD80\uC815\uD558\uACE0 \uC2F6\uC740 \uB9C8\uC74C\uC774 \uB4E0\uB2E4. \uC544\uB2C8\uB2E4. \uC544\uB2C8\uB77C\uACE0."), mdx("p", null, "--"), mdx("p", null, "\uB098\uB294 \uC2A4\uC2A4\uB85C\uB97C \uAD6C\uC6D0\uD558\uAE30 \uC704\uD574\uC11C \uC774 \uBAA8\uB4E0 \uBD88\uD3B8\uC744 \uC57D\uC18D\uD558\uACE0 \uACC4\uC18D \uBD88\uD589\uD574\uC57C \uD55C\uB2E4. \uB2E4\uB978 \uB9D0\uB85C, \uC800\uD56D\uD574\uC57C \uD55C\uB2E4. \uC774\uB807\uAC8C\uB294 \uC0B4\uC544\uAC08 \uC218 \uC5C6\uAE30 \uB54C\uBB38\uC774\uB2E4. \uB098\uBCF4\uB2E4 \uCEE4\uB2E4\uB780 \uAD6D\uAC00\uC640 \uC0AC\uD68C\uC640 \uC9D1\uB2E8, \uB0B4 \uC6B4\uBA85\uACFC \uB2A5\uB825, \uBAA8\uB4E0 \uC2E4\uC81C \uD639\uC740 \uAD00\uB150\uC801\uC778 \uAC83\uC740 \uC800\uD56D\uC758 \uB300\uC0C1\uC774 \uB41C\uB2E4."), mdx("blockquote", null, mdx("p", {
